// Mock of @minecraft/server-ui 2.x (rebuilt 2026-09-27).
// uiSim.queue: answers for the next forms, in order.
//   number n  -> ActionForm selection n (-1 = closed by the user)
//   "busy"    -> canceled with UserBusy
//   array     -> ModalForm formValues as given
//   {values}  -> ModalForm: values for the input elements only; filled into the chosen convention
// uiSim.modalMode: "withLabels" (formValues has a slot for every element) or "inputsOnly".
// v2.6.0: a function in the queue (or uiSim.auto when the queue is empty) is called with the form and returns the answer.
// v2.6.1: an ActionForm answer may be a Promise (the form stays open until it resolves).
// v2.26.0: uiManager.closeAllForms(player) closes that player's open ActionForm (a Promise answer still pending → canceled UserClosed),
//          recorded in uiSim.closed (player ids). The open ActionForm's player is form._player.
export const FormCancelationReason = { UserBusy: "UserBusy", UserClosed: "UserClosed" };
export const FormRejectReason = { MalformedResponse: "MalformedResponse", PlayerQuit: "PlayerQuit", ServerShutdown: "ServerShutdown" };

export const uiSim = { queue: [], shown: [], modalMode: "withLabels", emptyQueue: 0, closed: [] };
/** v2.26.0 열려 있는 (Promise 답을 기다리는) ActionForm: 플레이어 id → 닫기 함수 */
const openForms = new Map();

/** v2.26.0 게임의 uiManager: closeAllForms (열린 창 닫기) */
export const uiManager = {
  closeAllForms(player) {
    uiSim.closed.push(player?.id);
    const close = openForms.get(player?.id);
    if (close) close();
  },
};

/** v2.11.0: 글자 · 번역 글 (RawMessage) 확인 — 게임처럼 다른 모양이면 오류 */
function checkText(t, where) {
  if (typeof t === "string") return;
  const ok = (m) => m && typeof m === "object" && (typeof m.text === "string" || typeof m.translate === "string" || (Array.isArray(m.rawtext) && m.rawtext.every(ok)));
  if (!ok(t)) throw new Error(`${where}: string or RawMessage required, got ${JSON.stringify(t)}`);
}

/** 번역 글을 글자로 (시험용): translate 는 uiSim.lang 에서 찾고 없으면 [키] */
export function resolveText(t) {
  if (t === undefined || t === null) return "";
  if (typeof t === "string") return t;
  if (Array.isArray(t.rawtext)) return t.rawtext.map(resolveText).join("");
  if (typeof t.text === "string") return t.text;
  if (typeof t.translate === "string") return uiSim.lang?.[t.translate] ?? `[${t.translate}]`;
  return "";
}

function next(form) {
  if (uiSim.queue.length === 0) {
    if (typeof uiSim.auto === "function") return uiSim.auto(form);
    uiSim.emptyQueue++;
    return -1;
  }
  const a = uiSim.queue.shift();
  return typeof a === "function" ? a(form) : a;
}

export class ActionFormData {
  constructor() {
    this._title = "";
    this._body = "";
    this._buttons = [];
  }
  title(t) {
    this._title = t;
    return this;
  }
  body(t) {
    checkText(t, "ActionFormData.body");
    this._body = t;
    return this;
  }
  button(text, icon) {
    checkText(text, "ActionFormData.button");
    if (icon !== undefined && typeof icon !== "string") throw new Error(`ActionFormData.button: iconPath must be a string, got ${typeof icon}`);
    this._buttons.push({ text, icon });
    return this;
  }
  label(t) {
    this._buttons.push({ label: t });
    return this;
  }
  header(t) {
    return this.label(t);
  }
  divider() {
    return this;
  }
  async show(player) {
    uiSim.shown.push(this);
    this._player = player;
    let a = next(this);
    // v2.6.1: 답이 Promise 면 기다림 (창을 한동안 열어 둔 것처럼). v2.26.0: 그 사이 closeAllForms 면 닫힘 (UserClosed)
    if (a && typeof a.then === "function") {
      const id = player?.id;
      let closeFn;
      const closed = new Promise((r) => (closeFn = () => r(-1)));
      if (id !== undefined) openForms.set(id, closeFn);
      try {
        a = await Promise.race([a, closed]);
      } finally {
        if (openForms.get(id) === closeFn) openForms.delete(id);
      }
    }
    if (a === "busy") return { canceled: true, cancelationReason: FormCancelationReason.UserBusy };
    if (typeof a !== "number" || a < 0) return { canceled: true, cancelationReason: FormCancelationReason.UserClosed };
    const buttons = this._buttons.filter((b) => !("label" in b));
    if (a >= buttons.length) throw new Error(`selection ${a} out of range (${buttons.length} buttons)`);
    return { canceled: false, selection: a };
  }
}

export class MessageFormData {
  constructor() {
    this._title = "";
    this._body = "";
    this._buttons = [];
  }
  title(t) {
    this._title = t;
    return this;
  }
  body(t) {
    this._body = t;
    return this;
  }
  button1(t) {
    this._buttons[0] = t;
    return this;
  }
  button2(t) {
    this._buttons[1] = t;
    return this;
  }
  async show() {
    uiSim.shown.push(this);
    const a = next(this);
    if (a === "busy") return { canceled: true, cancelationReason: FormCancelationReason.UserBusy };
    if (typeof a !== "number" || a < 0) return { canceled: true, cancelationReason: FormCancelationReason.UserClosed };
    return { canceled: false, selection: a };
  }
}

export class ModalFormData {
  constructor() {
    this._title = "";
    this._elements = [];
    this._submit = "";
  }
  title(t) {
    this._title = t;
    return this;
  }
  label(t) {
    this._elements.push({ kind: "label", text: t });
    return this;
  }
  header(t) {
    this._elements.push({ kind: "header", text: t });
    return this;
  }
  divider() {
    this._elements.push({ kind: "divider" });
    return this;
  }
  textField(label, placeholder, o) {
    this._elements.push({ kind: "text", label, placeholder, def: typeof o === "string" ? o : o?.defaultValue ?? "" });
    return this;
  }
  dropdown(label, items, o) {
    this._elements.push({ kind: "dropdown", label, items, def: typeof o === "number" ? o : o?.defaultValueIndex ?? 0 });
    return this;
  }
  toggle(label, o) {
    this._elements.push({ kind: "toggle", label, def: typeof o === "boolean" ? o : !!o?.defaultValue });
    return this;
  }
  slider(label, min, max, o) {
    this._elements.push({ kind: "slider", label, min, max, def: o?.defaultValue ?? min });
    return this;
  }
  submitButton(t) {
    this._submit = t;
    return this;
  }
  async show() {
    uiSim.shown.push(this);
    const a = next(this);
    if (a === "busy") return { canceled: true, cancelationReason: FormCancelationReason.UserBusy };
    if (a === -1 || a === undefined) return { canceled: true, cancelationReason: FormCancelationReason.UserClosed };
    if (Array.isArray(a)) return { canceled: false, formValues: a };
    const inputs = this._elements.filter((e) => !["label", "header", "divider"].includes(e.kind));
    const given = a?.values ?? {};
    const valueOf = (e, i) => (i in given ? given[i] : e.label in given ? given[e.label] : e.def);
    let i = 0;
    const out = [];
    for (const e of this._elements) {
      if (["label", "header", "divider"].includes(e.kind)) {
        if (uiSim.modalMode === "withLabels") out.push(undefined);
        continue;
      }
      out.push(valueOf(e, i));
      i++;
    }
    return { canceled: false, formValues: out, _inputs: inputs.length };
  }
}
